"Alissonerdx 换人 v1.1（作者配方）：人物图先自动去背景，再把原视频里的人逐帧换成图中的人；背景、镜头、动作沿用原视频，人物的长相、发型、衣服按人物图（只有半身或坐姿也可以）。官方精简底模，DMD 8 步加速，① 原生节点；720p 每 5 秒约 16 分钟。": "Alissonerdx Character Swap v1.1 (author's recipe): the character image has its background removed automatically, then the person in the source video is replaced frame by frame with the person in the image; background, camera and motion follow the source video, while the character's looks, hairstyle and outfit follow the character image (half-body or seated images also work). Official pruned base model, DMD 8-step acceleration, ① native nodes; about 16 min per 5 s at 720p.",
