"Beat This!（ISMIR 2024，tools/beat_this_lib + models/beat_this/final0.ckpt，CPU）→ (节拍, 重拍, BPM)；用不了时返回 None": "Beat This! (ISMIR 2024, tools/beat_this_lib + models/beat_this/final0.ckpt, CPU) → (beats, downbeats, BPM); returns None if unavailable",
"Breeze TTS 2 权重仅限个人、研究和非商业用途；IndexTTS-2.5 使用 bilibili 模型许可（禁止用输出训练其他模型）；Qwen3-TTS 为 Apache 2.0；Seed-VC 为 GPL-3.0。仅可克隆本人或已获本人同意的声音，请勿用于冒充他人。": "Breeze TTS 2 weights are for personal, research, and non-commercial use only; IndexTTS-2.5 uses the bilibili model license (using its output to train other models is prohibited); Qwen3-TTS is Apache 2.0; Seed-VC is GPL-3.0. Clone only your own voice or a voice you have consent to use, and do not use it to impersonate others.",
"Breeze 没有“开心程度 0~100”这类数值旋钮，情绪强弱依靠措辞表达，网页的滑杆会将其转换为不同强度的措辞。": "Breeze has no numeric knob such as \"happiness 0–100\"; emotion intensity is expressed through wording, and the slider on the page converts it into phrasing of different intensity.",
"CIE L*（0~100）：sRGB → 线性 → 亮度 Y → L*（只要亮度差，不用 cv2）": "CIE L* (0~100): sRGB → linear → luminance Y → L* (only the luminance difference is needed, no cv2)",
"Civitai 上没有找到这个文件（可能不是从 Civitai 下载的，或作者改过文件）": "This file was not found on Civitai (it may not have been downloaded from Civitai, or the author changed it)",
