"Civitai 下载": "Civitai download",
"Civitai 无法识别该 API 密钥：请在 Civitai → 账号设置 → API Keys 重新生成并填写": "Civitai did not recognize this API key: regenerate it in Civitai → Account settings → API Keys and enter it again",
"Civitai 的一个模型 → 商店卡片 / 详情用的格式。keep：一定要留下的版本 id（我的下载：版本的底模不在这一栏时也要显示自己下的那个）": "A Civitai model → the format used by Store cards / details. keep: the version id that must be kept (My downloads: also show the version you downloaded when its base model is not in this column)",
"Civitai 的下载会 307 跳到 Cloudflare R2 的签名地址；urllib 跳转时会把 Authorization 头也带过去，R2 就回 400。跳转时去掉它": "Civitai downloads redirect (307) to a signed Cloudflare R2 address; urllib also forwards the Authorization header on redirect, and R2 then replies 400. Drop it on redirect",
"Civitai 的级别：1 PG、2 PG-13，4 及以上不显示。只留 PG / PG-13（没标级别的不留）": "Civitai content levels: 1 PG, 2 PG-13; 4 and above are hidden. Keep only PG / PG-13 (unrated items are dropped)",
"Civitai 要求登录：请先在上方填写 API 密钥": "Civitai requires sign-in: enter your API key above first",
