"Qwen 先改好一帧，H3 参考原视频整段重新生成。大部分换衣：整件换掉、换成完全不同的款式；动作和脸都不错（脸相似度约 0.93）": "Qwen edits one frame first, then H3 regenerates the whole video using the source video as reference. Suits most outfit changes: replacing the whole garment with a completely different style; motion and face are both good (face similarity about 0.93)",
