"Qwen 改好一帧后，Viggle 照着这一帧把整段重拍。最在意光照和脸跟原视频一样时；原视频光线复杂（暖光、逆光、偏色）时尤其值得开。实测光照最接近原视频（换衣：脸亮度差 0.7、相似 0.953）": "After Qwen edits one frame, Viggle reshoots the whole clip from that frame. Best when lighting and face matching the source video matter most; especially worthwhile when the source has complex lighting (warm light, backlight, color cast). Measured lighting is closest to the source (outfit change: face brightness difference 0.7, similarity 0.953)",
"Qwen 改的是窗口里的第几帧（钉在这一帧上）；自己放的图不知道对应哪一帧：不钉，只当参考": "Qwen edits which frame in the window (pinned to this frame); an image you add yourself doesn't map to a known frame: not pinned, used only as a reference",
