"一次批量的计数和一句话：网页、Agent、推送都用这一份": "One batch's counts and a one-line summary: shared by the page, Agent and notifications",
"一次提交 = 一行：视频指纹、时长、候选点（只有数字和类别）、用户选的段落、当时推荐的段落": "One submission = one row: video fingerprint, duration, candidate points (numbers and categories only), the segments the user chose, the segments recommended at the time",
"一次放几个视频：每个视频按配方分段、生成、质检，不过就换种子重做，最后拼回原视频。": "Add several videos at once: each video is split into segments by the recipe, generated and quality-checked; if it fails, it is redone with a new seed, and finally spliced back into the original video.",
"一段 5 秒约 17 分钟": "About 17 minutes for a 5 s clip",
"一段成品放在原视频的哪里：返回 (b0 原视频里从哪开始, gs 成品里从哪开始, gd 用多长, 选到结尾没有)": "Where a result segment sits in the source video: returns (b0 start in source video, gs start in result, gd duration used, whether selection reaches the end)",
