"估计的进度 0~1：转格式算前 5%，识别按“音频长度 × 这台机器上次的速度”估；超过预计时间就慢慢逼近 98%，等真的做完": "Estimated progress 0–1: format conversion counts for the first 5%; recognition is estimated from audio length × this machine's last speed; once the estimate is exceeded it slowly approaches 98% until actually done",
