"你为 Qwen-Image 2.1 的「局部重画」写一条指令。工作方式：程序把用户涂抹的区域连同周围一圈裁出来作为图 1，涂抹的部分涂成灰色；": "You write one instruction for Qwen-Image 2.1 Inpaint. How it works: the program crops the area the user painted together with a ring of surroundings as image 1, with the painted part filled gray;",
"你为文生图模型写一段画面描述。用户的原话通常很短，但里面的动作、手和拍摄视角常常很具体——模型最容易画错的正是这些。你要把它写成模型能逐项照做的描述。": "You write a scene description for a text-to-image model. The user's own words are usually short, but the actions, hands and camera angle in them are often very specific, and these are exactly what the model most easily gets wrong. Write it so the model can follow it item by item.",
"你好，很高兴认识你。今天的天气不错，我们一起去河边走走吧，顺便聊聊最近发生的事情。": "Hello, nice to meet you. The weather is lovely today. Let's take a walk by the river and chat about what has happened lately.",
"你真的以为": "Do you really think",
"你真的以为[停顿 1.5秒]我会放过你吗？": "Do you really think [Pause 1.5s] I'll let you off?",
"佩戴耳机效果最佳。仅作用于底部播放条当前播放的内容，不影响配音、换声的试听。": "Best with headphones. Applies only to what is playing in the bottom player bar; does not affect previews in Text to Speech or Voice changer.",
"使用": "Use",
