"使用 Google 翻译将名称和说明译为中文（触发词、文件名保持不变）": "Use Google Translate to translate names and descriptions into Chinese (trigger words and file names stay unchanged)",
"使用 PotPlayer 自带的 large-v3-turbo，可同时导出 SRT 字幕。识别完成后可直接编辑、复制或下载 TXT。": "Uses PotPlayer's built-in large-v3-turbo and can also export SRT subtitles. After recognition you can edit, copy, or download TXT directly.",
