"先改好一帧，H3 参考原视频整段重新生成。大部分换衣：整件换掉、换成完全不同的款式；动作和脸都不错（脸相似度约 0.93）": "Fix one frame first, then H3 regenerates the whole clip using the original video as reference. Best for most outfit changes: replacing the whole garment with a completely different style; motion and face hold up well (face similarity about 0.93)",
"先看增强后的提示词，改好再生成": "Review the enhanced prompt and edit it before generating",
"先记下这一段，再从白色标（当前画面）开始加一段；白色标在某一段中间时从那里切开": "Note this segment first, then add a segment starting at the white marker (current frame); if the white marker is inside a segment, it is split there",
