"关键帧够密（开头两个关键帧相隔不超过 0.7 秒）：拖进度条本来就流畅，不需要播放副本（结果按文件的修改时间 / 大小缓存）": "Keyframes are dense enough (the first two keyframes are no more than 0.7 s apart): scrubbing is already smooth, no playback copy is needed (results cached by file modified time / size)",
"关闭": "Close",
"关闭后，打开视频只显示画面，点播放按钮或缩略图上的": "When off, opening a video shows only the picture; play it with the play button or the thumbnail's",
"关闭后，打开视频只显示画面，点播放按钮或缩略图上的 ▶ 才播放；播放页和连续预览不受影响": "When off, opening a video shows only the picture; it plays only after clicking the play button or the ▶ on a thumbnail. The Player and continuous preview are not affected",
