"关闭模板后，提示词将原样发送给模型，请写完整": "With the template turned off, the prompt is sent to the model as is; please write it in full",
"关闭画面": "Close view",
"关闭窗口时：只结束这个应用启动的后台（口令摘要对得上；应用里重启过也算）和它的推理引擎。不是自己的一概不动": "When closing the window: only ends the backend started by this app (the key digest matches; restarts within the app count too) and its inference engine. Anything not its own is left alone.",
"关闭（Esc）": "Close (Esc)",
"关闭（隐藏到右下角托盘，音乐继续播放）": "Close (hide to the tray at bottom right; music keeps playing)",
"关闭（默认）：同一个原视频的片段、版本和拼接视频叠成一格，点开查看。开启：全部平铺显示": "Off (default): clips, versions and spliced videos of the same source video are stacked into one cell; open it to view. On: show everything flat",
"关闭：提示词框中的内容将原样发送给模型，“要换掉的人”一栏也不再使用。输入框为空时按 Tab 或回车，可填入原模板后再修改。": "Off: the text in the prompt box is sent to the model as is, and the \"Person to replace\" field is no longer used. When the box is empty, press Tab or Enter to insert the original template, then edit it.",
"关闭：框里的字原样发给模型——从“查看完整提示词”复制整段来改时关掉，不然会再套一次模板。": "Off: the text in the box is sent to the model as is. Turn this off when you copy the whole prompt from “View full prompt” to edit it; otherwise the template is applied again.",
