"参考图是穿在人身上的衣服照片时开启：先把衣服单独提取成白底图再参考，镂空和露肤处按图 1 人物的肤色画，不照搬参考图模特的肤色。每张参考图约多 2～3 分钟，同一张只提取一次": "Turn on when the reference image is a photo of clothes worn on a person: the garment is first extracted onto a white background and then used as the reference; cut-out and exposed-skin areas use the skin tone of the person in Image 1, not that of the reference model. Adds about 2–3 minutes per reference image; each image is extracted only once",
