"参考生成（人物、衣服、场景按参考图，动作和镜头按参考视频）；也可同时放入。关键帧、尾帧、开头片段、声音、引导视频位于“更多素材”中。": "Reference generation (character, outfit and scene follow the reference image; motion and camera follow the reference video); you can also use both. Keyframes, last frame, opening clip, audio and guide video are under “More assets”.",
