"参考生成：以原视频为参考视频、人物图为参考图，使用官方底模按结构化提示词重新生成整段。画面更美观、更清晰，但动作不一定逐帧一致；最长 15 秒；默认使用 ② 秋叶节点（14 步），速度较慢。": "Reference generation: the source video is used as the reference video and the person image as the reference image, and the official base model regenerates the whole clip from a structured prompt. The result looks better and sharper, but motion may not match frame by frame. Up to 15 s. Uses the ② Qiuye nodes (14 steps) by default, which is slower.",
