"后台将重新启动，约需 10~30 秒，完成后页面将自动刷新。配音引擎不会重新载入。": "The backend will restart, taking about 10–30 s; the page refreshes automatically when done. The voice engine is not reloaded.",
"后台尚未载入预览接口，请在设置中重启 Studio 后再试。": "The backend has not loaded the preview API yet. Restart Studio in Settings and try again.",
