"后台正在算这个视频：让它换成全速（用户点了按钮在等）": "The background is computing this video: switch it to full speed (the user clicked the button and is waiting)",
"后台每 20 秒看一次：开启了手机访问、并且 Tailscale 有地址，就在那个地址上监听；关掉或地址变了就停掉 / 重新监听。": "The backend checks every 20 s: if phone access is on and Tailscale has an address, listen on that address; stop / re-listen when it is turned off or the address changes.",
