"后台用哪个 exe：做好了就用 StudioServer.exe，不然 python.exe": "Which exe the back end uses: StudioServer.exe if built, otherwise python.exe",
"后台的 /api/boot（很轻，不查引擎）：{'boot', 'owner', 'pid'}；连不上 / 不像 Studio → None": "Backend /api/boot (very light, does not check the engine): {'boot', 'owner', 'pid'}; unreachable / does not look like Studio → None",
"后台记录": "Activity log",
"后台记录：生图时提示词增强、AI 助手写提示词，以及这里直接问官方增强小模型时，后台每一步的输入和输出（不算在对话历史里）": "Activity log: every step's input and output for prompt enhancement when generating images, AI Assistant prompt writing, and direct questions to the official enhancement model here (not counted in chat history)",
