"和 onnxruntime.InferenceSession 一样的用法：run(None, {输入名: 数组}) → [输出数组, …]": "Used the same way as onnxruntime.InferenceSession: run(None, {input name: array}) → [output array, …]",
"和参考视频": "and reference video",
"和图片": "and image",
"和换人的区别：换人保留原视频的背景，人物图要去背景；动作迁移连背景一起用人物图的，不去背景。": "Unlike character swap, which keeps the source video's background and needs a cut-out character image, motion transfer also uses the character image's background, so no cut-out is needed.",
"和网页上点“生成”一样的改衣设置（应用默认：参考生成 + 动作跟随 + 720p 加速 8 步；配方里可选 Viggle 重拍）": "Same Outfit change settings as clicking \"Generate\" on the page (app default: reference generation + pose guidance + 720p accelerated 8 steps; recipes may choose Viggle re-shoot)",
"和身体或物体怎么贴合（贴身还是宽松、垂下还是绷紧、遮住哪里、露出哪里）。用户只给了大致方向时，替他选定一个具体、好看的方案写出来。": "How it fits the body or object (close-fitting or loose, hanging or taut, what it covers, what it shows). If the user gave only a rough direction, choose a specific, attractive option for them and write it out.",
"和这段成品用的是同一个完整原视频（都选了“拼接”）的其他成品：可以一起拼回去（多段拼接，2026-11-05 用户要求）": "Other results that use the same full source video as this result (all chose “Splice”): they can be spliced back together (multi-segment splice, requested by the user 2026-11-05)",
