"增强会改掉姿势 LoRA 认的固定指令，所以按原话生成。": "Enhancement would alter the fixed instruction the pose LoRA recognizes, so it generates from your original wording.",
"增强写出来的指令很长，要改的那件事常常只有一句，容易改不到位。打开后把主要改动写在指令的最前面和最后面，并注明左右（人物的左边在画面右边）。默认关。": "Enhanced instructions are long, and the one thing to change is often only a sentence, so it may not be applied. When on, put the main change at the very start and end of the instruction and state left/right (a person's left is the right side of the image). Off by default.",
