"实测：改衣 720p 快约 4.6 倍（170 秒 / 778 秒），画面稍柔，大动作时可能有拖影。": "Measured: outfit change at 720p is about 4.6 times faster (170 s / 778 s); picture is slightly softer, and large motion may leave ghosting.",
