"实测：生视频官方原版首帧 480p 用时约为默认的 0.6 倍（34 秒 / 54 秒），画质同样好，动作略大。": "Measured: official original first-frame video at 480p takes about 0.6 times the default time (34 s / 54 s) with equally good quality and slightly larger motion.",
