"将另一侧的声音少量混入，类似音箱的聆听效果，长时间佩戴耳机更舒适。单侧录音的偏向感也会减轻。": "Mixes a little of the opposite side into each ear, like listening on speakers, which is more comfortable over long headphone sessions. Also softens the one-sided feel of single-sided recordings.",
