"开": "On",
"开“匹配原视频色调”可以在生成后调回来": "Turn on “Match source video tone” to correct it after generation",
"开启后，在这台手机上按住页面标题（例如“播放”）约 1 秒再松开，验证面容 ID 就能进入私密空间，不用再输密钥。不会显示任何按钮；别的设备上按住标题没有反应。": "When on, press and hold the page title (for example “Player”) on this phone for about 1 second and release, then verify Face ID to enter Private space, no key needed. No button is shown; holding the title on other devices does nothing.",
"开启后，每生成一段视频，在后台用 CPU 自动检查一遍（约 10～20 秒，不占显卡、不影响排队）：人物不见了、动作和原视频差得多、改衣后长相和原视频差别大。有问题的视频在缩略图上标出，点开可跳到对应的秒数。注意：很小的脸上嘴、鼻子那种变形查不出来。关闭（默认）时不做任何检查。": "When on, each generated video is automatically checked in the background on the CPU (about 10–20 s, no GPU use, no effect on the queue): missing person, motion far from the source video, face differing greatly from the source video after an outfit change. Problem videos are flagged on the thumbnail; open them to jump to the matching second. Note: distortion of the mouth or nose on a very small face cannot be detected. When off (default), no check is done.",
