"开启（默认）：将填写的内容放入此做法的模板，再发送给模型（模板位于“高级参数”最下方）。": "On (default): your input is placed into this method's template and then sent to the model (the template is at the bottom of Advanced).",
"开启（默认）：电脑在播放条上开启控制后，可以从电脑控制这台设备的播放，锁屏后也可以。为了暂停后还能被电脑继续，暂停时会播放无声音频，最长 30 分钟。": "On (default): after the computer enables control on the playback bar, it can control playback on this device, even when the screen is locked. So the computer can resume after a pause, silent audio plays while paused, for up to 30 minutes.",
"开启）": "On)",
"开启：左边导航栏变宽，图标旁边显示页面名称。关闭（默认）：窄导航栏": "On: the left sidebar widens and shows page names next to the icons. Off (default): narrow sidebar",
"开启：左边的缩略图放不下时叠在一起（像一叠文件），鼠标移上去抽出来。关闭（默认）：平铺，可以上下滚动": "On: thumbnails on the left stack when they do not fit (like a pile of files) and fan out on hover. Off (default): laid out flat, scrollable up and down",
"开启：打开视频（点缩略图、详情、放大原视频、素材库里的视频）就开始播放，生成完成后也自动播放。关闭：打开视频只显示画面，点播放按钮或缩略图上的": "On: opening a video (thumbnail tap, details, enlarged original, videos in Assets) starts playback, and finished generations also autoplay. Off: opening a video shows only the picture; play it with the play button or the thumbnail's",
"开启：打开视频（点缩略图、详情、放大原视频、素材库里的视频）就开始播放，生成完成后也自动播放。关闭：打开视频只显示画面，点播放按钮或缩略图上的 ▶ 才播放。播放页和连续预览不受影响。": "On: videos start playing as soon as they are opened (thumbnail, details, enlarged original, videos in Assets) and automatically after generation finishes. Off: opening a video shows only the picture; click the play button or the ▶ on the thumbnail to play. The Player page and continuous preview are not affected.",
