"快捷键：B 涂抹、E 擦除、W 智能选取，按住 Ctrl 临时换成另一种；Ctrl+Z 撤销。滚轮缩放（右栏的小图里按住 Ctrl 再滚）；放大后按住空格、鼠标右键或中键拖动可移动画面，点左上角的百分比还原。": "Shortcuts: B paint, E erase, W smart select; hold Ctrl to switch temporarily to the other. Ctrl+Z undoes. Scroll to zoom (hold Ctrl and scroll in the thumbnail in the right column); when zoomed in, hold Space, right or middle mouse button and drag to pan; click the percentage at the top left to reset.",
