"找换装点": "Find outfit-change points",
"把 H3 选项接进工作流：稀疏注意力 / INT8 注意力接在采样用的模型上（BasicGuider '11' 前面），VAE 换文件": "Wire H3 options into the workflow: sparse attention / INT8 attention attach to the sampling model (before BasicGuider '11'), and the VAE file is swapped",
"把 names[1:]（参考图）换成提取出来的衣服图（就地覆盖 ComfyUI 输入文件夹里的那张）；同一张图只提取一次": "Replace names[1:] (reference images) with the extracted outfit images (overwriting the one in ComfyUI's input folder in place); the same image is extracted only once",
"把 src 里 keep 的几段（秒，按帧对齐）按顺序接起来存成 out（画面 + 声音一起裁，帧准确）": "Join the keep segments of src (seconds, frame-aligned) in order and save as out (video and audio cropped together, frame-accurate)",
"把‘": "Replace ‘",
"把一单的工作流交给视频引擎，等它做完，返回 outputs（显存地址空间不够时自动释放 / 重启后重试）": "Hand a job's workflow to the video engine, wait for it to finish, and return outputs (auto-frees / retries after restart when VRAM address space is insufficient)",
"把一张图放进素材库的某个文件夹（默认“提取的衣服”）：硬链接（不多占空间，删一边另一边还在），不同盘时复制。返回 (相对路径, 原来就有)": "Put an image into a folder in Assets (default \"Extracted outfits\"): hard link (takes no extra space; deleting one side keeps the other), copy if on different drives. Returns (relative path, already existed)",
"把任务里的图（原图、参考图、遮罩）写进 ComfyUI 的输入文件夹：返回 (图名列表, 遮罩名, 原图尺寸)": "Write the task's images (original, reference images, mask) into ComfyUI's input folder: returns (list of image names, mask name, original size)",
"把做好的临时文件换成正式文件（旧的先挪成 .redo-old）；调用 undo() 换回旧的，commit() 删掉旧的": "Swap the finished temporary file in for the real file (the old one is first moved to .redo-old); call undo() to swap the old one back, commit() to delete the old one",
"把原视频和当时选的这几段放回剪辑，可以重新调整片段再生成": "Put the original video and the segments selected at the time back into the editor, so you can adjust them and generate again",
"把各模块接到这里的日志、空间、显卡调度上（正式启动和开发测试 devtest/run.py 共用）。": "Connect each module to the logging, spaces and GPU scheduling here (shared by the real launch and the dev test devtest/run.py).",
"把图 1 中的灰色区域重画，与周围的皮肤、衣服、头发和光线自然衔接：": "Redraw the gray area in image 1 so that it blends naturally with the surrounding skin, clothing, hair and lighting:",
"把工作流交给视频引擎，返回任务编号。编号自己定（uuid）：提交那一下超时（引擎正忙着载入别的模型），也认得出它收没收下": "Hand the workflow to the video engine and return the job ID. The ID is chosen by us (uuid): if the submit times out (engine busy loading another model), we can still tell whether it was accepted",
"把带标点的文字和逐字时间戳对齐，切成字幕句：句号/问号等处断句；太长时在逗号处断；长时间停顿也断。": "Align text with punctuation to word-level timestamps and split it into subtitle sentences: break at periods / question marks; break at commas when too long; also break at long pauses.",
"把当前播放位置设为开始": "Set the current playback position as the start",
"把当前播放位置设为结束": "Set the current playback position as the end",
"把缓存里的时长 / 作者填进 items（就地加 'dur' / 'artist'），缺的放到后台读；返回缺几个。": "Fill the cached duration / artist into items (adds 'dur' / 'artist' in place); missing ones are read in the background; returns how many are missing.",
"把网页的选择翻译成该模型官方支持的请求：只传 spec 里声明过的参数，其余一律用官方默认。": "Translate the web page's choices into the request officially supported by that model: pass only the parameters declared in spec, and use official defaults for everything else.",
"把视频里的人整个换成另一个人": "Replace the whole person in the video with another person",
"把这一段开头那一帧（原画质）存进素材库": "Save this segment's first frame (original quality) to Assets",
"把这张图的部件找出来存着（显卡锁由调用方拿着）": "Find the parts of this image and keep them (the GPU lock is held by the caller)",
"把选中范围的开始设到当前画面": "Set the start of the selection to the current frame",
"把选中范围的结束设到当前画面（含这一帧）": "Set the end of the selection to the current frame (inclusive)",
