"按文件指纹去 Civitai 查出这些 LoRA 是哪个模型（只读文件、不改动文件本身）": "Identify which model these LoRAs belong to on Civitai by file fingerprint (files are only read, never modified)",
"按最近一次使用的时间计算；最近 1 小时内用过的不会删除": "Based on last use; anything used within the last hour is not deleted",
"按此概率移除最高概率的候选，使文字更具新意。0 表示关闭。": "Removes the most probable candidates at this probability, making the text more novel. 0 turns it off.",
"按百万像素和宽高比算出图尺寸（32 的倍数）": "Compute the image size from the megapixels and aspect ratio (multiples of 32)",
"按短边计算，长边随首帧比例变化。480p 速度最快；720p 更清晰，但明显更慢、占用显存更多。“自定义”可填写短边（如 640）或宽×高（如 832x480），取 32 的倍数。": "Based on the short side; the long side follows the first frame's aspect ratio. 480p is fastest; 720p is sharper but noticeably slower and uses more VRAM. Custom accepts the short side (e.g. 640) or width×height (e.g. 832x480), in multiples of 32.",
"按类型筛选": "Filter by type",
"按类型筛选：只看视频、音频或图片": "Filter by type: video, audio or images only",
"按类型默认": "Type default",
"按编号查一单（不受列表条数限制）": "Look up a job by ID (not limited by the list length)",
"按自然段": "By paragraph",
"按语音段批量识别，提速 2~8 倍，长音频质量略有下降。": "Recognizes by speech segment in batches, 2–8× faster; quality on long audio drops slightly.",
"按钮": "Button",
"按顺序拼接成一段完整视频，存入视频库": "Splice in order into one complete video and save to the video library",
"挑出几段要换的（大约每 5 秒一段）：每段的开头、结尾都卡在音乐重音或定格 / 大动作上（两者都卡上的优先），每段": "Pick a few segments to change (about 5 s each): each starts and ends on a music accent or a freeze / big motion (both together preferred); each segment",
"挑出几段要换的（大约每 5 秒一段）：每段的开头、结尾都卡在音乐重音或定格 / 大动作上（两者都卡上的优先），每段 2.5–8 秒，其余保持原视频；推荐完可以再拖动调整": "Pick a few segments to replace (about one every 5 seconds): each segment starts and ends on a music accent or a freeze frame / big movement (segments matching both are preferred), 2.5–8 s each, with the rest kept from the original video; you can drag to adjust after the suggestion",
"挑染": "Highlights",
"挑逗、带着嘲讽": "Teasing, mocking",
"挪威语": "Norwegian",
"换一个视频": "Choose another video",
"换一版": "Try another version",
"换上": "Swap in",
"换人": "Character swap",
"换人 / 换头 LoRA 在 4~5 秒的连续镜头最稳，超过 10 秒容易走样；更长也更慢。": "Character swap / face swap LoRAs are most stable on continuous shots of 4–5 s; beyond 10 s the result tends to drift, and longer clips are slower.",
"换人 v1.1 + DMD 加速": "Character swap v1.1 + DMD acceleration",
"换人 v1.1（作者配方）：人物图先自动去背景，再把原视频里的人逐帧换成图中的人；背景、镜头、动作沿用原视频，人物的长相、发型、衣服按人物图（只有半身或坐姿也可以）。官方精简底模，DMD 8 步加速，": "Character swap v1.1 (author recipe): the character image has its background removed automatically, then the person in the source video is replaced frame by frame with the person in the image. Background, camera and motion follow the source video; the person's looks, hairstyle and outfit follow the character image (a half-body or seated image also works). Official pruned base model, DMD 8-step acceleration, ",
"换人 · 审美优先": "Character swap · Aesthetics first",
"换人 · 新版": "Character swap · New version",
"换人 · 新版（Character Swap v1.1 作者的模板）": "Character swap · New version (Character Swap v1.1 author's template)",
"换人 · 还原优先": "Character swap · Fidelity first",
"换人新版、动作迁移、换脸 LoRA、Viggle 重拍都自带，不用管": "Built in for the new character swap, motion transfer, face swap LoRA and Viggle remake; no need to set",
"换人需要放入一张人物图（要换成的那个人）": "Character swap needs a character image (the person to swap in)",
"换位置": "Change location",
"换声": "Voice changer",
"换声任务：沿用配音任务的队列、日志、取消、作品/历史记录；“段”= 原录音按停顿切开的一块。": "Voice changer task: reuses the voiceover task's queue, log, cancel and Saved / History; a \"segment\" = one block of the original recording split at pauses.",
"换声作品": "Voice changer saved",
"换声和原录音时间轴相同：按原录音每句的时间窗，取出换声结果里落在这段时间的字，做成一一对应的句子。": "The voice-changed result and the original recording share the same timeline: for each sentence's time window in the original recording, take the words of the result that fall in that window and build one-to-one sentences.",
"换声成品": "Voice changer results",
"换声的原录音：任意音频/视频/网页录音 → 44.1kHz 单声道 16 位 WAV（引擎内部会再按模型需要重采样）。": "Original recording for voice changer: any audio / video / web recording → 44.1kHz mono 16-bit WAV (the engine resamples again internally as the model needs).",
"换声结果未识别出字幕，仅可通过聆听对比": "No subtitles were recognized for the voice changer result; compare by listening only",
"换声：亲自演绎，转换为他人的声音": "Voice changer: perform it yourself, converted into someone else's voice",
"换头": "Face swap",
"换头 · 头像的脸部描述": "Face swap · Face description of the portrait",
"换头 · 换脸 LoRA": "Face swap · Face swap LoRA",
"换头 · 换脸 LoRA（UntMods 作者：只用触发词）": "Face swap · Face swap LoRA (UntMods author: trigger word only)",
"换头 · 换脸 LoRA（UntMods）要的：官方精简 + 这个 LoRA": "Face swap · Face swap LoRA (UntMods) needs: Official pruned + this LoRA",
"换头需要放入一张头像（新的那张脸，最好是清晰的正脸）": "Face swap needs an avatar (the new face, preferably a clear front-facing one)",
"换成什么衣服": "What outfit to change into",
"换成这个字幕文件？": "Switch to this subtitle file?",
"换掉": "Replace",
"换脸": "Face swap",
"换脸 LoRA": "Face swap LoRA",
"换脸 LoRA（UntMods）": "Face-swap LoRA (UntMods)",
"换脸 LoRA（默认）": "Face swap LoRA (default)",
"换脸 LoRA：原视频作为参考视频，换成头像里的脸和发型；身体、衣服、动作、背景沿用原视频。官方精简底模，官方加速 8 步（480p 不加速），": "Face swap LoRA: the source video is used as the reference video, with the face and hairstyle replaced by those in the avatar image; body, outfit, motion and background follow the source video. Official pruned base model, official 8-step acceleration (none at 480p), ",
"换衣": "Outfit change",
"换衣时光照、脸要和原视频一样": "Outfit change when lighting and face must match the source video",
"换衣时程序从提示词里认出了什么（完整提示词窗口里显示，方便确认写的有没有被认出来）": "What the program recognized from the prompt for an outfit change (shown in the full prompt window so you can check whether what you wrote was recognized)",
"换衣时要保留的衣物 / 配饰，和去掉“保留……”那句以后剩下的要求。返回 (keep, rest)；没写保留就是 ('', 原话)": "Garments / accessories to keep in an outfit change, and the remaining request after removing the “keep…” sentence. Returns (keep, rest); if no keep is written, ('', original text)",
"换衣：": "Outfit change: ",
"换衣；24 fps，画面清晰": "Outfit change; 24 fps, sharp picture",
