"推荐": "Suggest",
"推荐 按所选尺寸": "Recommended for the selected size",
"推荐分段": "Suggested segments",
"推荐帧": "Suggested frames",
"推荐设置照官方模板。默认就用推荐设置；想改时直接改，清空或点「恢复推荐」回到推荐值。每种用法（文生图、改图、局部重画）各记各的。": "Recommended settings follow the official template and are used by default. Edit them directly; clear the field or click Restore recommended to go back. Each mode (text to image, image edit, inpaint) keeps its own.",
"推荐：": "Recommended:",
"推荐：24 fps、清晰，脸和动作不变": "Recommended: 24 fps, sharp, face and motion unchanged",
"推荐：换出来的脸和头像最像": "Recommended: the swapped face most resembles the portrait",
"推荐：背景、镜头、动作沿用原视频，人物按人物图": "Recommended: background, camera and motion follow the source video; character follows the character image",
"推进一条：锁内领取 → 锁外处理（质检 / 拼接 / 通知可能几十秒，不挡别的批量和用户操作）→ 锁内提交（应用这期间的取消 / 重做 / 换版）": "Advance one item: claim under lock → process outside lock (quality check / splice / notify can take tens of seconds, without blocking other batches or user actions) → commit under lock (applying cancel / redo / version switch made in the meantime)",
"推进一次批量：返回 True = 有改动": "Advance one batch: returns True = changed",
"推送的标题和正文。私密空间和别的任务一样：不说是什么、不报数字（F21；以前批量通知会带上视频数 / 段数 / 质检数）": "Push title and body. Private space is treated like other tasks: says nothing about what it is, reports no numbers (F21; earlier batch notifications included video / segment / quality-check counts)",
"描述": "Description",
"描述修改后整张图的样子（请勿写“把…换成…”），例如：一位长发女子穿着白色短袖 T 恤站在海边，阳光，写实摄影": "Describe how the whole image looks after the edit (don't write “replace … with …”), e.g. A woman with long hair in a white short-sleeve T-shirt standing by the sea, sunlight, realistic photography",
"描述想要的画面": "Describe the image you want",
