"描述要生成的画面，中文即可": "Describe the image to generate",
"描述设计": "Design from description",
"描述（可选）": "Description (optional)",
"提交一个 SAM3 工作流，返回保存下来的遮罩（numpy bool 列表，用完删文件）": "Submit a SAM3 workflow and return the saved masks (list of numpy bool, files deleted after use)",
"提交一个工作流、等完成（取消时中断 ComfyUI），进度写进 j；返回 history 里的 outputs": "Submit a workflow and wait for it to finish (interrupts ComfyUI on cancel), writes progress into j; returns the outputs in history",
"提交失败": "Submission failed",
"提交时超时了：引擎多半已经收下（它忙的时候回话慢）。按编号在队列 / 记录里找，找到返回 True；引擎回话了但没有这一单返回 False": "Submission timed out: the engine has most likely accepted it (it replies slowly when busy). Look it up by ID in the queue / history; returns True if found; returns False if the engine replied but doesn't have this job",
