"提示词": "Prompt",
"提示词不改，直接点“生成”即可；改了就按新的提示词生成这一段。按 Ctrl + Enter 也可以生成": "If the prompt is unchanged, just click “Generate”; if changed, this segment is generated from the new prompt. Ctrl + Enter also generates",
"提示词中未提及的参考会自动在末尾补充一句。使用参考时，官方原版自动切换为 Ref2VA。H3 也可不放首帧，仅按文字和这些素材生成。点击“AI 优化”时，这些素材会一并提供给 AI 助手。": "References not mentioned in the prompt are appended automatically as a sentence at the end. When references are used, the official base switches to Ref2VA automatically. H3 can also generate without a first frame, from text and these assets alone. When you click AI optimize, these assets are also provided to the AI Assistant.",
