"改图": "Edit image",
"改图后处理失败，保留原图：": "Post-processing of the edit failed; original image kept: ",
"改图时脸和背景基本不变；int8 与原精度 bf16 出图几乎一样、快一倍。参数按老王论坛作者的设置": "When editing, the face and background stay essentially unchanged; int8 gives nearly the same output as the original bf16 precision and is twice as fast. Parameters follow the Laowang forum author's settings",
"改图时，要改成的新内容一定写具体、写满：衣服写颜色、材质、款式、剪裁、细节和穿在身上的样子（贴身还是宽松、长度、露出哪里）；": "When editing, write the new content to be applied specifically and completely: for clothing, color, material, style, cut, details and how it sits on the body (close-fitting or loose, length, what it shows);",
"改好一帧后，Viggle 照着这一帧把整段重拍。最在意光照和脸跟原视频一样时；原视频光线复杂（暖光、逆光、偏色）时尤其值得开。实测光照最接近原视频（换衣：脸亮度差 0.7、相似 0.953）": "After one frame is edited, Viggle re-shoots the whole clip based on that frame. Best when lighting and a face matching the source video matter most; especially worth enabling when the source video has complex lighting (warm light, backlight, color cast). In testing, lighting was closest to the source video (outfit change: face brightness difference 0.7, similarity 0.953)",
"改录音": "Edit recording",
