"最多再添加 2 张，例如一件衣服、一个背景或另一个人物。上方的原图为图 1（Picture 1），此处依次为图 2、图 3。提示词按以下方式书写最准确：": "You can add up to 2 more images, such as a garment, a background or another person. The original image above is Picture 1; these become Picture 2 and Picture 3 in order. The prompt is most accurate when written as follows: ",
"最多再添加 2 张，例如一件衣服、一个背景或另一个人物。上方的原图为图 1（Picture 1），此处依次为图 2、图 3。提示词按以下方式书写最准确：Make the woman in Picture 1 wear the outfit from Picture 2, keep her face, pose and background unchanged.": "Add up to 2 more images, such as an outfit, a background or another person. The source image above is Picture 1; these are Picture 2 and Picture 3 in order. Prompts are most accurate when written like this: Make the woman in Picture 1 wear the outfit from Picture 2, keep her face, pose and background unchanged.",
"最多再添加 2 张，例如一件衣服、一张脸、画风图或另一个人物。上方的原图为图 1，此处依次为图 2、图 3。指令用中文按「图 N」称呼即可，例如：将图1女性穿上图2的服装，保持图1女性的脸、发型、姿势和背景不变。": "Add up to 2 more images, such as an outfit, a face, a style image or another person. The source image above is Picture 1; these are Picture 2 and Picture 3 in order. Refer to them as “Picture N” in the instruction, for example: Make the woman in Picture 1 wear the outfit from Picture 2, keeping her face, hairstyle, pose and background from Picture 1 unchanged.",
