"每个功能适合什么、不适合什么": "What each feature suits and does not suit",
"每个视频做完后，把各段的最终版拼回原视频，得到完整的视频": "After each video is done, the final version of each segment is spliced back into the original video to produce the complete video",
"每个视频建一个图集": "Create one album per video",
"每个预设都必须有名称（system prompt 可留空，即直接对话）": "Every preset must have a name (system prompt can be left empty, meaning direct chat)",
"每块最长（秒）": "Maximum per block (s)",
"每块转换后自动通过语音识别核对，吞字、变字的块将更换种子重做；也可在“分块详情”中单独重做某一块。通过成品下方的“": "Each block is checked automatically by speech recognition after conversion; blocks with dropped or altered words are redone with a new seed; you can also redo a single block in “Block details”. Use the “",
"每块转换后自动通过语音识别核对，吞字、变字的块将更换种子重做；也可在“分块详情”中单独重做某一块。通过成品下方的“⇄ 对比原声”可逐句对比。": "After each block is converted, speech recognition checks it automatically; blocks with dropped or changed words are redone with a new seed. You can also redo a single block in “Block details”. Use “⇄ Compare original” below the result to compare sentence by sentence.",
"每块转换后通过语音识别分别比对原录音与结果，准确率未达到“通过标准”（吞字、变字）时更换种子自动重做。不影响声音本身；多次重做仍未通过时，保留最佳结果并标记为“建议检查”。语气夸张、气声较多的录音本身识别准确率较低，可适当调低标准。": "After each block is converted, speech recognition compares the original recording and the result separately; if accuracy falls below the “pass threshold” (dropped or changed words), the block is redone automatically with a new seed. This does not affect the voice itself. If a block still fails after repeated redos, the best result is kept and marked “Check recommended”. Exaggerated or breathy recordings are inherently harder to recognize accurately, so you can lower the threshold as needed.",
"每张图至少使用的 token 数：越多识别越细致，反推提示词越准确。0 表示模型默认，建议 1024。": "Minimum tokens used per image: more means finer recognition and a more accurate reverse-engineered prompt. 0 means the model default; 1024 is recommended.",
"每条最多行数": "Max lines per entry",
"每次最多拼接 40 段": "At most 40 segments can be spliced at a time",
"每段": "Each segment",
"每段均使用": "Every segment uses",
"每段最多几秒：Viggle 14 秒、H3 150 秒（引擎会把更长的截短）": "Max seconds per segment: Viggle 14 s, H3 150 s (the engine truncates longer ones)",
"每段最长字数": "Max characters per segment",
"每段生成后自动通过语音识别核对，读错、漏读的段落将": "After each segment is generated, speech recognition checks it automatically; misread or skipped segments will be",
"每段生成后通过语音识别与原文比对；准确率未达到“通过标准”（漏读、错读）时更换种子自动重做。不改变声音本身，仅挑选更准确的结果；多次重做仍未通过时，保留最佳结果并标记为“建议检查”。": "After each segment is generated, it is compared with the original text by speech recognition; when accuracy falls below the “pass threshold” (missed or misread words), the seed is changed and the segment is redone automatically. The voice itself is unchanged; only the more accurate result is picked. If it still fails after several redos, the best result is kept and marked “Needs review”.",
"每行最多字数": "Max characters per line",
"比对“有没有读错”之前：去掉标记和标点，数字统一成阿拉伯数字（原文写 123、识别出“幺二三”或“一百二十三”都算对）": "Before checking whether it was misread: remove markers and punctuation and normalize numbers to Arabic digits (if the original reads 123, a recognized spoken-digit form or a spelled-out form both count as correct)",
