"生图与配音轮流使用显卡：配音 / 换声 / 识别需要显卡时，生图会在完成当前图片后让出显卡，其余图片待对方使用完毕后自动继续生成；生图引擎闲置 5 分钟后也会自动退出并释放显存。": "Images and Text to Speech take turns using the GPU: when Text to Speech / Voice changer / recognition needs the GPU, image generation yields it after the current image and resumes the remaining images automatically once the other finishes; the image engine also exits automatically after 5 minutes idle, releasing VRAM.",
"生图任务拿显卡：等配音那边用完（期间可以取消）。拿到返回 True。": "Image task takes the GPU: waits until text to speech is finished (can be canceled meanwhile). Returns True once acquired.",
"生图前先释放配音模型的显存：": "Free the voiceover model's VRAM before generating images: ",
"生图前：配音引擎里载入的模型、本地翻译模型、提示词模型都先从显存里放掉（下次用到时自动重新载入）": "Before generating images: release the models loaded in the voiceover engine, the local translation model and the prompt model from VRAM (they reload automatically when next used)",
