"生成的图片位于下方图库中，打开大图后可左右翻页，按 I 查看提示词和种子；“存入音源库”后，也可在播放页的“AI 生图”文件夹中查看。私密空间中生成的图片仅保存在私密空间内。": "Generated images are in the gallery below; open one full size to flip left and right, and press I to view the prompt and seed. After “Save to Sources”, you can also find them in the “AI Images” folder on the Player page. Images generated in the private space are saved only inside the private space.",
