"给网页本地粗筛用：{'vk': 2 位提示, 'vks': 提示盐}；没有可用的密钥 → {'vk': None}": "For coarse local filtering on the web page: {'vk': 2-character hint, 'vks': hint salt}; if no usable key → {'vk': None}",
