"网页上的三种改法 → AuK 官方中文模板": "The three edit modes on the page → AuK official Chinese templates",
"网页上给人看的提示词模板（不能改）：‹…› 是会被换掉的部分": "Prompt template shown to people on the web page (not editable): ‹…› marks the parts that will be replaced",
"网页上能选的东西：采样器、调度器、加速缓存、LoRA、高清修复的放大方式、能不能单独放大。引擎开着时问它（以它为准）。": "Options selectable on the web page: samplers, schedulers, acceleration cache, LoRAs, hi-res fix upscale methods, and whether standalone upscaling is available. Asked from the engine while it is running (the engine is authoritative).",
"网页优先将整个自然段一次生成，段落超过此字数时才在句号处切分，因此语气连贯；每段均使用同一参考音色，音色不会漂移。字数越多越连贯，但单段出错的概率也越高（会由自动核对发现并重做）。": "The web page generates a whole natural paragraph at once where possible and splits at periods only when a paragraph exceeds this character count, so the tone stays coherent; every segment uses the same reference voice, so the voice does not drift. More characters give better coherence, but a higher chance of an error in a single segment (found by the automatic check and redone).",
"网页会在此处切分并插入精确时长的静音，标记本身不会被朗读。仅写": "The page splits here and inserts silence of exact duration; the tag itself is not read aloud. Just write ",
"网页会在此处切分文字，插入一段真实的静音（时长精确，所有模型通用，标记本身不会被朗读）。": "The page splits the text here and inserts a real silence (exact duration, works with all models; the tag itself is not read aloud).",
"网页传来的“改视频”设置 → 检查过的 dict（不对就报错，提示看得懂的话）。": "“Edit video” settings from the web page → a validated dict (raises an error if invalid, with an understandable message).",
"网页传来的改动只留合法的：steps 1~100、cfg 0~20、采样器 / 调度器在列表里、mp（百万像素）0.25~6 或 'page'（按网页选的尺寸）；局部重画不改像素": "Only valid changes from the web page are kept: steps 1~100, cfg 0~20, sampler / scheduler in the list, mp (megapixels) 0.25~6 or 'page' (size chosen on the page); Inpaint does not change pixels",
"网页传来的生图设置 → 检查过的任务 dict（还没进队列）": "Image settings from the web page → validated task dict (not yet queued)",
"网页放了图、智能选取开着时先跑一遍（不用等第一次点）：存图 + 找部件。已经做过就直接返回": "When the web page has an image and smart select is on, run once first (no need to wait for the first click): save the image + find parts. If already done, return directly",
"网页文件：带版本号的长期缓存；其余每次问一下（ETag）。raw：已经生成好的内容（首页）": "Web files: versioned ones get long-term caching; the rest are checked each time (ETag). raw: already generated content (home page)",
"网页的操作：create（基于某一套新建）/ save（改名字或文字）/ delete / default / pick（系统指令选哪个版本：key + ver）": "Web page actions: create (new, based on a set) / save (rename or edit text) / delete / default / pick (which version of the system instructions: key + ver)",
"网页进入全屏：窗口盖住整个屏幕（连任务栏）。用 WinForms 自己的属性改（直接改窗口位置会被 WinForms 记的状态改回去）。": "Page enters full screen: the window covers the whole screen (including the taskbar). Set via WinForms' own properties (changing the window position directly would be reverted by WinForms' remembered state).",
