"长度不限，10~30 分钟的录音会在语句间最安静处自动切分为约 10 秒的小块转换，再按原时间轴拼接，成品与原录音时长相同。": "Any length. Recordings of 10–30 minutes are split at the quietest points between sentences into chunks of about 10 seconds, converted, then joined on the original timeline; the result has the same duration as the original recording.",
"长录音": "Long recording",
"长录音会在语句间最安静处切分为小块分别转换，每块前后各附带 1 秒上下文，转换后按原时间轴拼接，总时长与原录音完全一致。实测单块超过 20 秒时会开始吞掉“了”等轻声字，因此默认 10 秒。": "Long recordings are split into chunks at the quietest points between sentences and converted separately, each chunk with 1 second of context on both sides, then joined on the original timeline so the total duration matches the original exactly. In testing, chunks over 20 seconds begin to drop neutral-tone particles such as \"le\", so the default is 10 seconds.",
