"（推荐）：参考更准确。MiniMax H3 官方完整版（34GB，int8），只有首帧时使用 FL2VA，放入参考图 / 参考视频 / 参考音频时自动切换为 Ref2VA；放入参考视频（以它的动作为参考）时默认使用": "(Recommended): more accurate references. MiniMax H3 official full version (34GB, int8); with only a first frame it uses FL2VA, and when a reference image / reference video / reference audio is added it switches to Ref2VA automatically; when a reference video is added (using its motion as reference) it uses by default ",
"（推荐）：参考更准确。MiniMax H3 官方完整版（34GB，int8），只有首帧时使用 FL2VA，放入参考图 / 参考视频 / 参考音频时自动切换为 Ref2VA；放入参考视频（以它的动作为参考）时默认使用 ① 原生节点（20 步，较慢，动作节奏与参考视频更一致）；其余情况（首帧、首尾帧、只有参考图 / 参考音频）默认使用 ② 秋叶节点（14 步）。": " (recommended): more accurate reference. Official MiniMax H3 full model (34 GB, int8). Uses FL2VA with only a first frame and switches to Ref2VA automatically when a reference image, video or audio is added. With a reference video (used for motion), the ① native nodes are the default (20 steps, slower, motion timing closer to the reference); otherwise (first frame, first and last frames, or only a reference image or audio) the ② Qiuye nodes are the default (14 steps).",
