"：输入一句描述，例如“一位四十岁的男性旁白，声音低沉有磁性”，选择 Breeze 或 Qwen3 进行设计，一次生成多个候选，从中选择一个保存。": ": enter a one-sentence description, e.g. \"a male narrator in his forties, deep and magnetic voice\", choose Breeze or Qwen3 for design, generate several candidates at once and pick one to save.",
